import socket from "../socket";
import { useEffect, useState } from "react";
import api from "../api";

export default function Provider() {
  const [req, setReq] = useState(null);
  const [providerId, setProviderId] = useState(null);
  const [bookings, setBookings] = useState([]);

  useEffect(() => {
    // Get provider ID from token
    const token = localStorage.getItem("token");
    if (token) {
      try {
        const decoded = JSON.parse(atob(token.split(".")[1]));
        setProviderId(decoded.id);
        
        // Emit provider-online with actual provider ID
        socket.emit("provider-online", decoded.id);
      } catch (err) {
        console.error("Error decoding token:", err);
      }
    }

    // Listen for new booking requests
    socket.on("new-booking", (data) => {
      setReq(data);
    });

    // Listen for booking updates
    socket.on("booking-update", (data) => {
      console.log("Booking update:", data);
    });

    // Load provider's bookings
    loadBookings();

    return () => {
      socket.off("new-booking");
      socket.off("booking-update");
    };
  }, []);

  const loadBookings = async () => {
    try {
      const response = await api.get("/bookings/provider-bookings");
      setBookings(response.data);
    } catch (err) {
      console.error("Error loading bookings:", err);
    }
  };

  const handleAccept = async () => {
    if (req) {
      socket.emit("booking-response", { 
        status: "accepted", 
        bookingId: req.bookingId,
        providerId: providerId
      });
      setReq(null);
      loadBookings();
    }
  };

  const handleReject = async () => {
    if (req) {
      socket.emit("booking-response", { 
        status: "rejected", 
        bookingId: req.bookingId,
        providerId: providerId
      });
      setReq(null);
    }
  };

  const updateBookingStatus = async (bookingId, status) => {
    try {
      await api.post(`/bookings/status/${bookingId}`, { status });
      loadBookings();
    } catch (err) {
      console.error("Error updating booking:", err);
    }
  };

  return (
    <div style={{ padding: "20px" }}>
      <h1>Provider Dashboard</h1>
      <p>Welcome, Service Provider!</p>

      {req && (
        <div style={{ border: "2px solid #4CAF50", padding: "20px", marginBottom: "20px", borderRadius: "5px" }}>
          <h3>New Booking Request</h3>
          <p><strong>Service:</strong> {req.serviceName}</p>
          <p><strong>Location:</strong> {req.location}</p>
          <p><strong>User:</strong> {req.userName}</p>
          <button 
            onClick={handleAccept}
            style={{ padding: "10px 20px", marginRight: "10px", cursor: "pointer", backgroundColor: "green", color: "white", border: "none" }}
          >
            Accept
          </button>
          <button 
            onClick={handleReject}
            style={{ padding: "10px 20px", cursor: "pointer", backgroundColor: "red", color: "white", border: "none" }}
          >
            Reject
          </button>
        </div>
      )}

      {!req && (
        <p style={{ color: "orange" }}>No pending requests</p>
      )}

      <div>
        <h2>My Bookings</h2>
        {bookings.length === 0 ? (
          <p>No bookings yet.</p>
        ) : (
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ backgroundColor: "#f0f0f0" }}>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Service</th>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Location</th>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Status</th>
                <th style={{ padding: "10px", border: "1px solid #ccc" }}>Action</th>
              </tr>
            </thead>
            <tbody>
              {bookings.map((booking) => (
                <tr key={booking._id}>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>{booking.serviceName}</td>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>{booking.location}</td>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>
                    <span style={{ 
                      color: booking.status === "accepted" ? "green" : 
                             booking.status === "rejected" ? "red" : "orange" 
                    }}>
                      {booking.status}
                    </span>
                  </td>
                  <td style={{ padding: "10px", border: "1px solid #ccc" }}>
                    {booking.status === "pending" && (
                      <>
                        <button 
                          onClick={() => updateBookingStatus(booking._id, "accepted")}
                          style={{ padding: "5px 10px", marginRight: "5px", cursor: "pointer", backgroundColor: "green", color: "white", border: "none" }}
                        >
                          Accept
                        </button>
                        <button 
                          onClick={() => updateBookingStatus(booking._id, "rejected")}
                          style={{ padding: "5px 10px", cursor: "pointer", backgroundColor: "red", color: "white", border: "none" }}
                        >
                          Reject
                        </button>
                      </>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      <button 
        onClick={() => {
          localStorage.removeItem("token");
          window.location.href = "/";
        }}
        style={{ marginTop: "30px", padding: "10px 20px", cursor: "pointer" }}
      >
        Logout
      </button>
    </div>
  );
}
